1	import React from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { defineMessages, useIntl } from 'react-intl';
4	import { ZimmProductCardMedia } from '../../molecules/zimmProductCardMedia';
5	import type { ZimmProductCardMediaImage } from '../../molecules/zimmProductCardMedia';
6	import { ZimmProductCardContent } from '../../molecules/zimmProductCardContent';
7	import type { ZimmSizeChipValue } from '../../molecules/zimmSizeChipGroup';
8	
9	/**
10	 * SFCC-236 Step 6 — the organism that assembles Step 4's `ZimmProductCardMedia` and Step 5's
11	 * `ZimmProductCardContent` into the full product card, across the three confirmed variations.
12	 * Figma component set `Product-card`, node `40000223:2822` (20 variants: Size x State x Type x
13	 * Unavailable), file `wPiWmZZOVKnrENUWk2XWWm`. The variation matrix below reflects the resolved
14	 * `hidden`-attribute reading confirmed against the real assembled Card-content instances:
15	 *
16	 *   Home      (40000214:6141 default / 40002163:36593 hover)   — image + name only by default;
17	 *             bag/attributes/size-selector hidden always; hover reveals price; arrows appear
18	 *             (Media's own concern, driven purely by image count, not variation).
19	 *   PLP/PDP   (40002163:41441 default / 40002163:41459 hover)  — image + name + bag (always) +
20	 *             price by default, no attributes, size-selector hidden; hover hides price and
21	 *             reveals the size-selector in its place; arrows appear.
22	 *   Wishlist  (40002187:58446 default / 40002187:58458 hover)  — image + name + bag (always) +
23	 *             attributes (colour+size) + price by default, size-selector hidden; hover hides
24	 *             price and reveals the size-selector, confirmed identical to PLP's own hover reveal
25	 *             via node `40002187:58460` (the Wishlist hover instance carries no `hidden`
26	 *             attribute on "Size Selector" at all) — this is NOT what the SFCC-236 Jira AC text
27	 *             says (it only mentions the image switch + arrows for Wishlist hover), but the
28	 *             design is the source of truth here per AGENTS.md's doc-integrity rule.
29	 *
30	 * "Recently Viewed Full History" is not a fourth variation — the AC states it behaves exactly
31	 * like PLP, so callers pass `variation: 'plp'` for it.
32	 *
33	 * Unavailable=True is only confirmed in scope for the `plp` variation (out-of-stock + notify-me,
34	 * per the AC). Home/Wishlist ACs never mention an unavailable treatment, so no variation-specific
35	 * unavailable behaviour is added here for them — `isUnavailable` and `onNotifyMe` are threaded
36	 * through uniformly to `ZimmProductCardContent` (the only one of the two composed children that
37	 * has an `isUnavailable` concept at all — `ZimmProductCardMedia` has no such prop) exactly the
38	 * way Content already generically supports on its own, for any caller. This organism does not
39	 * itself restrict `showNotifyMe` to the `plp` variation; a Home/Wishlist caller that never passes
40	 * `onNotifyMe` gets no notify-me button, matching the "no variation-specific treatment invented
41	 * beyond what Media/Content already do generically" instruction this step was built against.
42	 *
43	 * KNOWN GAP: `ZimmProductCardMedia`'s `priority` prop (its LCP eager-load escape hatch) has no
44	 * passthrough here — every card composed via this organism lazy-loads its primary image. Not in
45	 * the given component contract for this step; flagged rather than added silently, since a PLP
46	 * page placing this organism above the fold would want it.
47	 */
48	
49	/** Re-exported under this organism's own name so a page-level caller never has to reach into a
50	 *  molecule's type — the shape itself is Media's own `ZimmProductCardMediaImage`, not a
51	 *  redeclaration (a hand-copied duplicate would silently drift from its source). */
52	export type ZimmProductCardImage = ZimmProductCardMediaImage;
53	
54	/** `ZimmProductCardContent`'s own already-derived heading-level type (`'h1' | 'h2' | 'h3'`,
55	 *  itself derived from `ZimmProductName`'s `as` prop) — read via `ComponentProps` off the
56	 *  component this organism actually forwards it to, rather than a hand-typed duplicate union. */
57	type ZimmProductCardHeadingLevel = React.ComponentProps<typeof ZimmProductCardContent>['headingLevel'];
58	
59	/**
60	 * Exported alongside `ZimmProductCardProps` (not just kept module-private) so a test/fixture can
61	 * build a properly *narrowed* per-variation props object — e.g.
62	 * `ZimmProductCardBaseProps & ZimmProductCardWishlistVariation` — instead of a value typed as the
63	 * full union. This matters for real, not just for convenience: TypeScript's excess-property
64	 * check on a *union* target is weak (a property valid on any one member is not flagged as excess
65	 * on a fresh literal discriminated toward a different member), so proving "the wishlist-only
66	 * fields don't exist on Home" needs an assignment to Home's own narrow shape specifically, not to
67	 * the union alias — see index.test.tsx's `@ts-expect-error` cases and its overloaded
68	 * `buildCardProps` helper.
69	 */
70	export type ZimmProductCardBaseProps = {
71	  /** Stable per-card identifier. Not used for any layout/behavioural decision — exposed as a
72	   *  `data-product-id` attribute on the root element as a DOM hook for QA automation/analytics,
73	   *  the same kind of caller-facing marker `data-testid` already serves in this build's other
74	   *  components, without overloading that attribute's own testing-only convention. */
75	  id: string;
76	  /** PDP destination, pre-site-prefixed by the caller — forwarded straight to
77	   *  `ZimmProductCardContent`'s own `href` (see that component's own JSDoc on trust level). */
78	  href: string;
79	  name: string;
80	  headingLevel: ZimmProductCardHeadingLevel;
81	  primaryImage: ZimmProductCardImage;
82	  hoverImage?: ZimmProductCardImage;
83	  images?: ZimmProductCardImage[];
84	  currentPrice?: string;
85	  originalPrice?: string;
86	  isPriceLoading?: boolean;
87	  isUnavailable?: boolean;
88	  /** Only meaningful when `isUnavailable` is true. See the module docblock for why this is not
89	   *  restricted to the `plp` variation at the type level. */
90	  onNotifyMe?: () => void;
91	};
92	
93	export type ZimmProductCardPlpVariation = {
94	  variation: 'plp';
95	  onAddToBag?: () => void;
96	  sizeChipValues?: ZimmSizeChipValue[];
97	  selectedSizeChipValue?: string;
98	  onSizeChipSelect?: (value: string) => void;
99	};
100	
101	export type ZimmProductCardHomeVariation = {
102	  variation: 'home';
103	  // No additions — Home never shows the bag, attributes, or size chips (see VARIATION_CONFIG).
104	};
105	
106	export type ZimmProductCardWishlistVariation = {
107	  variation: 'wishlist';
108	  /** Required, not optional — the Wishlist AC always shows the attributes line. */
109	  colour: string;
110	  size: string;
111	  /** Required — a wishlist card with no way to remove itself is a spec violation. */
112	  onRemove: () => void;
113	  /** Bag is always visible for Wishlist per the confirmed matrix above. */
114	  onAddToBag?: () => void;
115	};
116	
117	export type ZimmProductCardProps = ZimmProductCardBaseProps &
118	  (ZimmProductCardPlpVariation | ZimmProductCardHomeVariation | ZimmProductCardWishlistVariation);
119	
120	type ZimmProductCardVariation =
121	  | ZimmProductCardPlpVariation['variation']
122	  | ZimmProductCardHomeVariation['variation']
123	  | ZimmProductCardWishlistVariation['variation'];
124	
125	/**
126	 * Widened, not narrowed: every variation-specific field is optional here regardless of which
127	 * branch is actually active, purely so the component body below can destructure once with no
128	 * `if`/`switch` on `props.variation` — the extensibility AC requires every layout/visibility
129	 * decision to come from `VARIATION_CONFIG`, keyed by the discriminant, never a branching
130	 * statement. The exported `ZimmProductCardProps` discriminated union above is what actually
131	 * enforces correct usage at every call site (proven by the `@ts-expect-error` cases in
132	 * index.test.tsx) — this cast only relaxes internal access inside this file; it changes nothing
133	 * about what a caller may legally pass in.
134	 */
135	type ZimmProductCardVariationFields = Partial<
136	  Omit<ZimmProductCardPlpVariation, 'variation'> &
137	    Omit<ZimmProductCardWishlistVariation, 'variation'> &
138	    Omit<ZimmProductCardHomeVariation, 'variation'>
139	>;
140	
141	type ZimmProductCardVariationConfig = {
142	  showBag: boolean;
143	  showAttributes: boolean;
144	  showSizeChips: boolean;
145	  /** PLP/Wishlist: price is visible by default and hides on hover. */
146	  hoverHidesPrice: boolean;
147	  /** Home only: price is hidden by default and reveals on hover. */
148	  hoverRevealsPrice: boolean;
149	  /** PLP/Wishlist: the size-chip picker is hidden by default and reveals on hover. */
150	  hoverRevealsSizeSelector: boolean;
151	  showRemove: boolean;
152	};
153	
154	/**
155	 * The extensibility AC's actual mechanism: every layout/visibility decision this organism makes
156	 * reads from this table, keyed by `variation` — adding a future variation means adding a union
157	 * member above and one row here, touching no JSX. `index.tsx`'s render body contains no
158	 * `switch`/`if` on `props.variation` anywhere (verify with
159	 * `grep -n 'variation ===\|switch (variation)' index.tsx` — zero hits).
160	 */
161	const VARIATION_CONFIG: Record<ZimmProductCardVariation, ZimmProductCardVariationConfig> = {
162	  home: {
163	    showBag: false,
164	    showAttributes: false,
165	    showSizeChips: false,
166	    hoverHidesPrice: false,
167	    hoverRevealsPrice: true,
168	    hoverRevealsSizeSelector: false,
169	    showRemove: false,
170	  },
171	  plp: {
172	    showBag: true,
173	    showAttributes: false,
174	    showSizeChips: true,
175	    hoverHidesPrice: true,
176	    hoverRevealsPrice: false,
177	    hoverRevealsSizeSelector: true,
178	    showRemove: false,
179	  },
180	  wishlist: {
181	    showBag: true,
182	    showAttributes: true,
183	    showSizeChips: true,
184	    hoverHidesPrice: true,
185	    hoverRevealsPrice: false,
186	    hoverRevealsSizeSelector: true,
187	    showRemove: true,
188	  },
189	};
190	
191	const messages = defineMessages({
192	  // Interpolated with the product name, matching ZimmProductPrice's WAS/NOW pattern — Media's
193	  // own `removeLabel` prop is a plain string, so the interpolation happens here, at the one call
194	  // site that actually knows the product name.
195	  removeFromWishlist: {
196	    id: 'product_card.remove.from_wishlist',
197	    defaultMessage: 'Remove {name} from wishlist',
198	  },
199	});
200	
201	const ZIMM_PRODUCT_CARD_RECIPE = 'ZimmProductCard';
202	
203	/**
204	 * Organism — the full product card, composing `ZimmProductCardMedia` and `ZimmProductCardContent`
205	 * across the `home` / `plp` / `wishlist` variations. See the module docblock above for the
206	 * confirmed Figma variation matrix and this component's own recipe (`zimmProductCard.css.ts`) for
207	 * the stretched-link and hover-reveal mechanics that live entirely in CSS, not in this render
208	 * body — both children are always rendered in full, with every one of their own sub-parts; CSS
209	 * alone decides what is visible for a given variation and pointer capability.
210	 *
211	 * @param props see `ZimmProductCardProps` — a discriminated union on `variation`.
212	 */
213	export const ZimmProductCard = (props: ZimmProductCardProps) => {
214	  const {
215	    id,
216	    href,
217	    name,
218	    headingLevel,
219	    primaryImage,
220	    hoverImage,
221	    images,
222	    currentPrice,
223	    originalPrice,
224	    isPriceLoading,
225	    isUnavailable,
226	    onNotifyMe,
227	    variation,
228	  } = props;
229	
230	  const { onAddToBag, sizeChipValues, selectedSizeChipValue, onSizeChipSelect, colour, size, onRemove } =
231	    props as ZimmProductCardVariationFields;
232	
233	  const intl = useIntl();
234	  const config = VARIATION_CONFIG[variation];
235	
236	  // Both conditions required — an organism that sets isUnavailable without a real callback
237	  // should not show a dead notify-me button. Mirrors ZimmProductCardContent's own
238	  // showNotifyMeButton co-requirement.
239	  const showNotifyMe = Boolean(isUnavailable) && Boolean(onNotifyMe);
240	
241	  const removeLabel = config.showRemove ? intl.formatMessage(messages.removeFromWishlist, { name }) : undefined;
242	
243	  const styles = useMultiStyleConfig(ZIMM_PRODUCT_CARD_RECIPE, {
244	    hoverHidesPrice: config.hoverHidesPrice,
245	    hoverRevealsPrice: config.hoverRevealsPrice,
246	    hoverRevealsSizeSelector: config.hoverRevealsSizeSelector,
247	  });
248	
249	  return (
250	    <chakra.div __css={styles.root} data-testid="product-card" data-product-id={id}>
251	      <ZimmProductCardMedia
252	        primaryImage={primaryImage}
253	        hoverImage={hoverImage}
254	        images={images}
255	        swapOnHover={Boolean(hoverImage)}
256	        showControls
257	        onRemove={onRemove}
258	        removeLabel={removeLabel}
259	      />
260	      <ZimmProductCardContent
261	        name={name}
262	        headingLevel={headingLevel}
263	        href={href}
264	        currentPrice={currentPrice}
265	        originalPrice={originalPrice}
266	        isPriceLoading={isPriceLoading}
267	        showAttributes={config.showAttributes}
268	        colour={colour}
269	        size={size}
270	        showBag={config.showBag}
271	        isUnavailable={isUnavailable}
272	        onAddToBag={onAddToBag}
273	        showSizeChips={config.showSizeChips}
274	        sizeChipValues={sizeChipValues}
275	        selectedSizeChipValue={selectedSizeChipValue}
276	        onSizeChipSelect={onSizeChipSelect}
277	        showNotifyMe={showNotifyMe}
278	        onNotifyMe={onNotifyMe}
279	      />
280	    </chakra.div>
281	  );
282	};
283	
284	export default ZimmProductCard;
