import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import { MemoryRouter } from 'react-router-dom';
import theme from 'app/theme';
import { ZimmProductCard } from './index';
import type { ZimmProductCardImage } from './index';

vi.mock('../../atoms/zimmIcon', () => ({ ZimmIcon: () => null }));
vi.mock('../../../icons', () => ({
  ChevronLeftIcon: () => null,
  ChevronRightIcon: () => null,
  CloseIcon: () => null,
}));

const PRIMARY: ZimmProductCardImage = { src: 'primary.jpg', alt: 'Zimmermann dress, front' };
const GALLERY: ZimmProductCardImage[] = [
  { src: 'g1.jpg', alt: 'front' },
  { src: 'g2.jpg', alt: 'side' },
];

describe('PROBE: real cascade, no mocks', () => {
  test('close button (wishlist) — computed position vs Media own absolute intent', () => {
    render(
      <MemoryRouter>
        <IntlProvider locale="en" defaultLocale="en">
          <ChakraProvider theme={theme}>
            <ZimmProductCard
              id="p1"
              href="/product/1"
              name="Natura Dress"
              headingLevel="h3"
              primaryImage={PRIMARY}
              variation="wishlist"
              colour="Ivory"
              size="M"
              onRemove={vi.fn()}
              onAddToBag={vi.fn()}
            />
          </ChakraProvider>
        </IntlProvider>
      </MemoryRouter>,
    );

    const closeButton = screen.getByRole('button', { name: 'Remove Natura Dress from wishlist' });
    console.log('CLOSE computed position/top/right/zIndex:', getComputedStyle(closeButton).position, getComputedStyle(closeButton).top, getComputedStyle(closeButton).right, getComputedStyle(closeButton).zIndex);

    const bagButton = screen.getByRole('button', { name: 'Add to bag' });
    console.log('BAG computed position/zIndex:', getComputedStyle(bagButton).position, getComputedStyle(bagButton).zIndex);

    expect(true).toBe(true);
  });

  test('carousel arrow buttons (plp + gallery) — computed position should be relative, non-destructively', () => {
    render(
      <MemoryRouter>
        <IntlProvider locale="en" defaultLocale="en">
          <ChakraProvider theme={theme}>
            <ZimmProductCard
              id="p2"
              href="/product/2"
              name="Another Dress"
              headingLevel="h3"
              primaryImage={PRIMARY}
              images={GALLERY}
              variation="plp"
              onAddToBag={vi.fn()}
            />
          </ChakraProvider>
        </IntlProvider>
      </MemoryRouter>,
    );

    const nextButton = screen.getByRole('button', { name: 'Next image' });
    console.log('ARROW computed position/zIndex:', getComputedStyle(nextButton).position, getComputedStyle(nextButton).zIndex);
    const carouselWrapper = document.querySelector('[data-card-slot="carousel"]') as HTMLElement;
    console.log('CAROUSEL WRAPPER computed position:', getComputedStyle(carouselWrapper).position, getComputedStyle(carouselWrapper).top);
  });
});
EOF
